from .commisioning_file import CommissioningBaseFile
from .utils import info


class Scfc(CommissioningBaseFile):
    @info('Deleting')
    def delete(self, moc):
        moc_to_remove = self._find_moc(moc)
        self.cmdata.remove(moc_to_remove)

    @info('Updating')
    def add_params_to_moc(self, moc, params):
        moc_to_update = self._find_moc(moc)
        if params:
            moc_to_update.extend(params)

    @info('Updating')
    def remove_params_from_moc(self, moc, params):
        moc_to_update = self._find_moc(moc)
        for param in params:
            param_to_remove = self._find_param(moc_to_update, param)
            moc_to_update.remove(param_to_remove)

    def _find_moc(self, moc):
        return self.cmdata.find('%s[@distName="%s"]' % (moc.tag, moc.get('distName')))

    def _find_param(self, moc, param):
        return moc.find('%s[@name="%s"]' % (param.tag, param.get('name')))
